export const Group: Story = {
  parameters: {
    docs: {
      description: { story: "Wrap attachments in `AttachmentGroup` to lay them out in a horizontally scrollable, snapping row with an edge fade." },
      source: { code: "import { Icon } from "@/registry/erbium/ui/icon";
import type { IconProps } from "@/registry/erbium/ui/icon";
import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/erbium/ui/attachment";

interface Item {
  name: string;
  meta: string;
  icon?: IconProps["name"];
  src?: string;
}

const items: Item[] = [
  { icon: "file-text", meta: "PDF · 1.4 MB", name: "briefing-notes.pdf" },
  {
    meta: "PNG · 820 KB",
    name: "workspace.png",
    src: "https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=900&auto=format&fit=crop&q=80",
  },
  { icon: "table", meta: "CSV · 18 KB", name: "customers.csv" },
  { icon: "file-code", meta: "TSX · 12 KB", name: "renderer.tsx" },
];

export default function AttachmentGroupExample() {
  return (
    <div className="mx-auto w-full max-w-sm py-12">
      <AttachmentGroup className="w-full">
        {items.map((item) => {
          const { icon } = item;

          return (
            <Attachment key={item.name} className="w-64">
              {item.src === undefined ? (
                <AttachmentMedia>{icon !== undefined && <Icon name={icon} />}</AttachmentMedia>
              ) : (
                <AttachmentMedia variant="image">
                  <img src={item.src} alt={item.name} />
                </AttachmentMedia>
              )}
              <AttachmentContent>
                <AttachmentTitle>{item.name}</AttachmentTitle>
                <AttachmentDescription>{item.meta}</AttachmentDescription>
              </AttachmentContent>
              <AttachmentActions>
                <AttachmentAction aria-label={`Remove ${item.name}`}>
                  <Icon name="x" />
                </AttachmentAction>
              </AttachmentActions>
            </Attachment>
          );
        })}
      </AttachmentGroup>
    </div>
  );
}
" },
    },
  },
  render: GroupExample,
};

